cat > calc.py <<'PYEOF'
import sys, math
pdb = sys.argv[1]
RAD = {'C':1.70,'N':1.55,'O':1.52,'S':1.80}
MAXASA = {'A':129.0,'R':274.0,'N':195.0,'D':193.0,'C':167.0,'E':223.0,'Q':225.0,'G':104.0,'H':224.0,'I':197.0,'L':201.0,'K':236.0,'M':224.0,'F':240.0,'P':159.0,'S':155.0,'T':172.0,'W':285.0,'Y':263.0,'V':174.0}
T2O = {'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLU':'E','GLN':'Q','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
BB = set(['N','CA','C','O','OXT'])
atoms = []
for line in open(pdb):
    if not line.startswith('ATOM'):
        continue
    name = line[12:16].strip()
    if name.startswith('H') or name.startswith('D'):
        continue
    resname = line[17:20].strip()
    if resname not in T2O:
        continue
    resseq = int(line[22:26])
    x = float(line[30:38]); y = float(line[38:46]); z = float(line[46:54])
    el = line[76:78].strip()
    if not el:
        el = name[0]
    atoms.append((resseq, resname, name, el, x, y, z))
n = len(atoms)
sys.stderr.write('heavy atoms parsed: ' + str(n) + '\n')
NP = 400
pts = []
ga = math.pi * (3.0 - math.sqrt(5.0))
for k in range(NP):
    zz = 1.0 - 2.0 * (k + 0.5) / NP
    rr = math.sqrt(max(0.0, 1.0 - zz * zz))
    th = ga * k
    pts.append((rr * math.cos(th), rr * math.sin(th), zz))
PROBE = 1.4
co = [(a[4], a[5], a[6]) for a in atoms]
rd = [RAD.get(a[3], 1.70) + PROBE for a in atoms]
sasa = []
for i in range(n):
    xi, yi, zi = co[i]; ri = rd[i]
    nb = []
    for j in range(n):
        if i == j:
            continue
        xj, yj, zj = co[j]; rj = rd[j]
        d2 = (xi-xj)**2 + (yi-yj)**2 + (zi-zj)**2
        if d2 < (ri + rj) * (ri + rj):
            nb.append((xj, yj, zj, rj*rj))
    acc = 0
    for p in pts:
        px = xi + ri*p[0]; py = yi + ri*p[1]; pz = zi + ri*p[2]
        ok = True
        for (xj, yj, zj, rj2) in nb:
            if (px-xj)**2 + (py-yj)**2 + (pz-zj)**2 < rj2:
                ok = False
                break
        if ok:
            acc += 1
    sasa.append(4.0 * math.pi * ri * ri * acc / NP)
tot = {}
sc = {}
rnm = {}
for i, a in enumerate(atoms):
    k = a[0]
    rnm[k] = a[1]
    tot[k] = tot.get(k, 0.0) + sasa[i]
    if a[2] not in BB:
        sc[k] = sc.get(k, 0.0) + sasa[i]
CUT = 5.0
rows = []
for k in sorted(rnm):
    one = T2O[rnm[k]]
    trunc = [i for i, a in enumerate(atoms) if a[0] == k and a[2] not in BB and a[2] != 'CB']
    lost_sasa = sum(sasa[i] for i in trunc)
    partners = set()
    for i in trunc:
        xi, yi, zi = co[i]
        for j in range(n):
            if atoms[j][0] == k:
                continue
            xj, yj, zj = co[j]
            if (xi-xj)**2 + (yi-yj)**2 + (zi-zj)**2 < CUT*CUT:
                partners.add(j)
    rel = 100.0 * tot[k] / MAXASA[one]
    scv = sc.get(k, 0.0)
    rows.append((k, one, round(tot[k],1), round(rel,1), round(scv,1), len(trunc), round(lost_sasa,1), len(partners)))
out = open('out.tsv', 'w')
out.write('#resnum\tres\ttotal_sasa_A2\trel_sasa_pct\tsidechain_sasa_A2\tatoms_removed_by_Ala\tsasa_of_removed_atoms\tcontacts_within_5A\n')
for r in rows:
    out.write('\t'.join(str(v) for v in r) + '\n')
out.close()
